Random temporary emigration
This is the special case where \(\gamma' = \gamma''\). The probability of being unavailable at time \(t\) is the same regardless of whether the animal was available or unavailable at time \(t-1\). Availability has no memory. Each primary period, each animal independently draws its availability state with the same probability.
Under random temporary emigration, the proportion of animals available at any given time is simply \(1 - \gamma'\), and this proportion is constant across primary periods.
Random temporary emigration is a simpler model with one fewer parameter, and it is often a reasonable starting assumption. If you have no strong biological reason to expect that availability is persistent, it is a sensible default.
Use the sliders below to explore how the two gamma parameters shape availability patterns. Start with \(\gamma' \approx \gamma''\) for random emigration, then pull them apart to see Markovian behaviour emerge.


Code
viewof gp_te = Inputs.range([0, 0.99], {
  value: 0.8,
  step: 0.01,
  label: "γ′ — probability of staying unavailable (once already absent)"
})









Code
viewof gdp_te = Inputs.range([0, 0.99], {
  value: 0.3,
  step: 0.01,
  label: "γ″ — probability of becoming unavailable (if currently present)"
})









Code
{
  // Deterministic PRNG so the grid is stable as sliders move
  function mulberry32(a) {
    return function() {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a);
      t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t;
      return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296;
    };
  }

  const N_ANIMALS = 6;
  const N_PERIODS = 8;

  // Pre-generate a fixed pool of uniform draws (same seed every render)
  const rng  = mulberry32(1988);
  const pool = Array.from({ length: N_ANIMALS * N_PERIODS }, () =&gt; rng());

  // Simulate availability
  const avail = [];
  for (let i = 0; i &lt; N_ANIMALS; i++) {
    const row = [1]; // all present at period 1
    for (let t = 1; t &lt; N_PERIODS; t++) {
      const r = pool[i * N_PERIODS + t];
      row.push(row[t - 1] === 1
        ? (r &lt; gdp_te ? 0 : 1)   // present  → leaves    with prob γ″
        : (r &lt; gp_te  ? 0 : 1)); // absent   → stays away with prob γ′
    }
    avail.push(row);
  }

  // Summary statistics
  const flat        = avail.flat();
  const propUn      = flat.filter(x =&gt; x === 0).length / flat.length;
  const expectedUn  = gdp_te / (1 - gp_te + gdp_te);   // steady-state unavailability

  let runs = 0, runTotal = 0;
  for (let i = 0; i &lt; N_ANIMALS; i++) {
    let len = 0;
    for (let t = 0; t &lt; N_PERIODS; t++) {
      if (avail[i][t] === 0) { len++; }
      else if (len &gt; 0)      { runs++; runTotal += len; len = 0; }
    }
    if (len &gt; 0) { runs++; runTotal += len; }
  }
  const meanRun = runs &gt; 0 ? (runTotal / runs).toFixed(1) : "0.0";

  const diff     = Math.abs(gp_te - gdp_te);
  const isRandom = diff &lt; 0.05;
  const typeText = isRandom
    ? `&lt;strong style="color:#FFD700"&gt;Random&lt;/strong&gt; — γ′ ≈ γ″, availability at each period is independent of the previous one`
    : gp_te &gt; gdp_te
      ? `&lt;strong style="color:#FFD700"&gt;Markovian&lt;/strong&gt; — γ′ &gt; γ″, once absent animals tend to stay away for multiple periods`
      : `&lt;strong style="color:#FFD700"&gt;Markovian&lt;/strong&gt; — γ′ &lt; γ″, animals return quickly relative to how often they leave`;

  // Build grid rows
  let rows = `&lt;div&gt;&lt;/div&gt;`;
  for (let t = 0; t &lt; N_PERIODS; t++) {
    rows += `&lt;div style="font-size:11px;color:#888;text-align:center;padding-bottom:4px"&gt;P${t + 1}&lt;/div&gt;`;
  }
  for (let i = 0; i &lt; N_ANIMALS; i++) {
    rows += `&lt;div style="font-size:12px;color:#888;display:flex;align-items:center"&gt;Animal ${i + 1}&lt;/div&gt;`;
    for (let t = 0; t &lt; N_PERIODS; t++) {
      const ok = avail[i][t] === 1;
      rows += `&lt;div style="background:${ok ? "#1a3a2a" : "#3a1a1a"};border:1px solid ${ok ? "#00A68A" : "#FF5733"};border-radius:3px;height:34px;display:flex;align-items:center;justify-content:center;font-size:14px;color:${ok ? "#00A68A" : "#FF5733"}"&gt;${ok ? "&#10003;" : "&#10007;"}&lt;/div&gt;`;
    }
  }

  const el = document.createElement("div");
  el.style.cssText = "background:#202123;border-radius:8px;padding:16px;font-family:sans-serif;color:#cccccc";
  el.innerHTML = `
    &lt;div style="display:grid;grid-template-columns:80px repeat(${N_PERIODS},1fr);gap:3px;margin-bottom:8px"&gt;${rows}&lt;/div&gt;
    &lt;div style="display:flex;gap:20px;font-size:12px;color:#666;margin-bottom:14px"&gt;
      &lt;span style="color:#00A68A"&gt;&#10003; Available&lt;/span&gt;
      &lt;span style="color:#FF5733"&gt;&#10007; Unavailable (absent from study area)&lt;/span&gt;
    &lt;/div&gt;
    &lt;div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:12px"&gt;
      &lt;div style="background:#252525;border-radius:6px;padding:10px;text-align:center"&gt;
        &lt;div style="font-size:11px;color:#999;margin-bottom:4px"&gt;Expected unavailable&lt;/div&gt;
        &lt;div style="font-size:20px;color:#FF5733"&gt;${(expectedUn * 100).toFixed(1)}%&lt;/div&gt;
      &lt;/div&gt;
      &lt;div style="background:#252525;border-radius:6px;padding:10px;text-align:center"&gt;
        &lt;div style="font-size:11px;color:#999;margin-bottom:4px"&gt;Observed in simulation&lt;/div&gt;
        &lt;div style="font-size:20px;color:#cccccc"&gt;${(propUn * 100).toFixed(1)}%&lt;/div&gt;
      &lt;/div&gt;
      &lt;div style="background:#252525;border-radius:6px;padding:10px;text-align:center"&gt;
        &lt;div style="font-size:11px;color:#999;margin-bottom:4px"&gt;Mean absence run&lt;/div&gt;
        &lt;div style="font-size:20px;color:#cccccc"&gt;${meanRun} periods&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
    &lt;p style="font-size:13px;color:#999;margin:0"&gt;Type: ${typeText}&lt;/p&gt;
  `;
  return el;
}







Try setting \(\gamma' = \gamma''\) — the mean absence run drops close to 1 and the grid looks scattered with no obvious clusters. Then increase \(\gamma'\) well above \(\gamma''\) and watch long runs of consecutive absence appear. The mean absence run length in the stats above is a direct measure of how much memory the availability process has — and for Lily’s willow warblers, that number will be very large during the months the birds are on migration.

How many animals are there, and are they surviving?
Two of the most fundamental questions in ecology and conservation are: how many individuals of a species are there, and how well are they surviving? How many Atlantic salmon are in the River Dee? What proportion of juveniles survive to adulthood? Is that survival rate declining? Is a conservation intervention actually working?

Lily, in your case these questions become; How many willow warblers are present at your study sites? How well are they surviving between breeding seasons? Is survival declining? Are any interventions or habitat changes making a difference?
These are not easy questions to answer, and the reason comes down to the same problem that runs through this entire tutorial: you will never see every bird that is there.

These questions sound simple but they’re not. And the reason for that comes down to a problem that seems simple but is hard to deal with.


The naive approach
Imagine I want to estimate how many otters live along a stretch of river. I go out and count them. I spot 23 otters.
So there are 23 otters?
Maybe. But I wouldn’t bet a £100 that I saw every single otter that was there. Some might’ve been in burrows. Some were maybe around the bend in the river. Some maybe saw me coming and hid. The 23 I counted is not the true population size. It is the true population size multiplied by my probability of detecting any given otter.
\[\text{Count} = N \times p\]
where \(N\) is the true number of otters and \(p\) is my detection probability. If \(p = 1\) (i.e. I have 100% chance of seeing each otter), my count equals the true population. If \(p &lt; 1\), and it is almost always less than 1, my count is an underestimate. How badly it underestimates depends entirely on how low \(p\) is.
This is imperfect detection. This is the default condition of almost every single wildlife survey ever conducted. If you have ever counted animals in the field and assumed that count represented the true number present, you were almost certainly wrong.


Mark individuals
Here is where the “mark” part of mark-recapture comes in. The idea is pretty simple:

If you catch some animals, mark them, release them, and then go back and catch animals again, the proportion of marked animals in your second sample tells you something about how many unmarked ones you missed.

Say I catch 20 otters, tag each one with a unique ID, and release them back into the river. A week later I come back and catch another 20 otters. Of these 20, I find that 5 of them have the tags I put on a week ago. So I recaptured 5 out of the 20 I originally marked. That recapture rate of \(\frac{5}{20} = 25\%\) is an estimate of my detection probability. And if I only detected 25% of last weeks marked animals in my second sample, I probably only detected about 25% of unmarked animals too. Which means my second sample of 20 likely represents about 25% of the true population, meaning there are roughly \(\frac{20}{0.25} = 80\) otters in total.
That’s the Lincoln-Petersen estimator, and we’ll work through it properly on the next page. For now, the main idea is that recaptures allow us to figure out detection probability, which is what allows us to estimate true population size rather than just report a count and hope for the best.
All good and well but there’s actually a second problem on top of imperfect detection.


The second problem: individuals can die
Individual animals are not immortal and static. They move, disperse, and/or they die.
This matters a lot because it creates a new version of the detection problem.
Imagine I tag 50 fish in June. In August I go back and sample again. I catch 30 fish, of which 12 have tags. Fine - same as before with the otters. But now I want you to think about the 38 tagged fish I did not recapture. Those “non-recaptures” have two possible explanations:

They are still alive, I just did not catch them. My detection probability is (almost always) less than 100%, so that’s entirely plausible. (This is what we assumed above with the otters)
They are dead.

A non-recapture has two possible meanings: missed, or dead. The crap part of that: both explanations predict exactly the same observation in your data - a zero. In both cases you don’t see the fish but the biological distinction between missed and dead is obviously important…
If you cannot separate these two explanations, you cannot estimate either detection probability or survival probability reliably. They are completely tangled up in each other.
The following simulation hopefully makes this tangible (don’t worry about the code). We follow 50 tagged individuals across four sampling occasions, assuming a survival probability of 0.75 between occasions and detection probabilities that range from 0.30 to 0.80 across the four surveys.


Code
library(ggplot2)
library(dplyr)

set.seed(1988)

n_tagged &lt;- 50
occasions &lt;- 4

phi_true &lt;- 0.75
p_true &lt;- c(0.3, 0.5, 0.6, 0.8)

survival_mat &lt;- matrix(NA, nrow = n_tagged, ncol = occasions)
survival_mat[, 1] &lt;- 1

for (t in 2:occasions) {
  survival_mat[, t] &lt;- rbinom(n_tagged, 1, survival_mat[, t - 1] * phi_true)
}

detection_mat &lt;- matrix(NA, nrow = n_tagged, ncol = occasions)
for (t in 1:occasions) {
  detection_mat[, t] &lt;- rbinom(n_tagged, 1, survival_mat[, t] * p_true[t])
}

observed_counts &lt;- colSums(detection_mat)
true_alive &lt;- colSums(survival_mat)

summary_df &lt;- data.frame(
  occasion = 1:occasions,
  true_alive = true_alive,
  observed = observed_counts
)

ggplot(summary_df) +
  geom_col(aes(x = occasion, y = true_alive),
           fill = "#00A68A", alpha = 0.4, width = 0.6) +
  geom_col(aes(x = occasion, y = observed),
           fill = "#FF5733", alpha = 0.8, width = 0.3) +
  labs(
    x = "Sampling occasion",
    y = "Number of tagged individuals",
    caption = "Green = truly alive  |  Orange = actually detected"
  ) +
  scale_x_continuous(breaks = 1:occasions) +
  theme_dark_site()









The green bars show how many animals are truly alive at each occasion. The orange bars show how many we actually detect. The gap between them is entirely due to imperfect detection, not death. But if I only showed you the orange bars and asked you to calculate a survival rate, you’d probably conclude things look ok, but based on the green bars, this population is crashing fast.
This is where using the right stats matters a lot. Imagine this is a critically endangered population, and you’re the conservation officer. If you use basic stats you’re going to tell everyone “don’t worry, the species are doing fine. They’re stable”. In doing so, you’ve likely just condemned a species to extinction. We don’t use complicated stats for the sake of it. We use it because there’s a god damned moral imperative to make sure you make the best decision with the data you have.


Try it yourself: dead or hiding?
Before we formalise this problem, try to get a proper sense of it. Below are four tagged animals. Their detection histories are shown one occasion at a time. Each time your survey draws a blank, you must decide: was the animal dead, or was it alive and just not detected?


Code
{
  const animals = [
    { id: "Animal #7",  alive: [1,1,1,1], detected: [1,0,0,1] },
    { id: "Animal #12", alive: [1,1,0,0], detected: [1,1,0,0] },
    { id: "Animal #3",  alive: [1,1,1,1], detected: [1,0,1,0] },
    { id: "Animal #19", alive: [1,0,0,0], detected: [1,0,0,0] }
  ];

  let ai = 0, occ = 0, guesses = [], phase = "playing";

  const el = document.createElement("div");
  el.style.cssText = "background:#202123;border-radius:8px;padding:20px;color:#cccccc;font-family:sans-serif";

  function draw() {
    const a = animals[ai];
    const n = a.alive.length;

    let tiles = `&lt;div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px"&gt;`;
    for (let i = 0; i &lt; n; i++) {
      let bg="#2a2a2a", bd="#444", icon="·", sub="";
      if (phase === "revealed") {
        if (a.detected[i])    { bg="#1a3a2a"; bd="#00A68A"; icon="✓"; sub="Detected"; }
        else if (a.alive[i])  { bg="#2e2a10"; bd="#FFD700"; icon="○"; sub="Alive, missed"; }
        else                  { bg="#3a1a1a"; bd="#FF5733"; icon="✗"; sub="Dead"; }
      } else {
        if (i &lt; occ) {
          if (a.detected[i])         { bg="#1a3a2a"; bd="#00A68A"; icon="✓"; sub="Detected"; }
          else if (guesses[i]==="d") { bg="#3a1a1a"; bd="#FF5733"; icon="✗"; sub="You said: Dead"; }
          else if (guesses[i]==="h") { bg="#2e2a10"; bd="#FFD700"; icon="?"; sub="You said: Hiding"; }
        } else if (i === occ) {
          bg="#1a2535"; bd="#4a9eff"; icon="→"; sub="Current";
        }
      }
      tiles += `&lt;div style="flex:1;min-width:72px;background:${bg};border:2px solid ${bd};border-radius:6px;padding:8px;text-align:center"&gt;
        &lt;div style="font-size:11px;color:#888"&gt;Occasion ${i+1}&lt;/div&gt;
        &lt;div style="font-size:22px;margin:4px 0"&gt;${icon}&lt;/div&gt;
        &lt;div style="font-size:11px;color:#aaa;min-height:14px"&gt;${sub}&lt;/div&gt;
      &lt;/div&gt;`;
    }
    tiles += `&lt;/div&gt;`;

    let action = "";
    if (phase === "revealed") {
      const allAlive = a.alive.every(x =&gt; x === 1);
      const diedAt   = a.alive.indexOf(0);
      const summary  = allAlive
        ? `&lt;strong style="color:#00A68A"&gt;This animal was alive for all four occasions.&lt;/strong&gt; Every non-detection was a missed observation, not a death.`
        : `This animal died between occasion ${diedAt} and occasion ${diedAt+1}. Non-detections before that were misses; after that, the animal was gone.`;
      let wrong = 0, total = 0;
      for (let i = 0; i &lt; n; i++) {
        if (!a.detected[i] && guesses[i] != null) {
          total++;
          if (guesses[i] !== (a.alive[i] ? "h" : "d")) wrong++;
        }
      }
      const verdict = total === 0 ? ""
        : wrong &gt; 0
          ? `&lt;p style="color:#FFD700;font-size:13px;margin:8px 0 0"&gt;You got ${wrong} of ${total} guess${total&gt;1?"es":""} wrong — and there was no way to know from the data alone. That is the point.&lt;/p&gt;`
          : `&lt;p style="color:#aaa;font-size:13px;margin:8px 0 0"&gt;You got them all right this time — but could you be certain? The data alone cannot prove it.&lt;/p&gt;`;
      const nxt = ai &lt; animals.length - 1
        ? `&lt;button id="nxtA" style="margin-top:12px;background:#333;color:#ccc;border:1px solid #555;padding:8px 20px;border-radius:6px;cursor:pointer"&gt;Try another animal →&lt;/button&gt;`
        : `&lt;p style="color:#666;font-size:13px;margin-top:12px"&gt;You have seen all four animals. The same ambiguity lives in every zero in every dataset.&lt;/p&gt;`;
      action = `&lt;div style="background:#1a2a1a;border:1px solid #00A68A;border-radius:6px;padding:14px"&gt;
        &lt;p style="margin:0;color:#ccc;font-size:14px"&gt;${summary}&lt;/p&gt;${verdict}&lt;/div&gt;${nxt}`;
    } else if (occ &gt;= n) {
      action = `&lt;div style="text-align:center"&gt;
        &lt;p style="color:#999;margin-bottom:10px"&gt;All occasions complete. Ready to see what actually happened?&lt;/p&gt;
        &lt;button id="revBtn" style="background:#4a9eff;color:#fff;border:none;padding:10px 24px;border-radius:6px;cursor:pointer;font-size:14px"&gt;Reveal the truth&lt;/button&gt;
      &lt;/div&gt;`;
    } else {
      if (a.detected[occ]) {
        action = `&lt;div style="background:#1a3a2a;border:1px solid #00A68A;border-radius:6px;padding:14px;text-align:center"&gt;
          &lt;p style="margin:0;color:#00A68A;font-weight:bold"&gt;✓ Detected at occasion ${occ+1}!&lt;/p&gt;
          &lt;p style="margin:6px 0 0;color:#999;font-size:13px"&gt;The animal appeared in your survey. Definitely alive at this point.&lt;/p&gt;
        &lt;/div&gt;
        &lt;div style="text-align:center;margin-top:12px"&gt;
          &lt;button id="nxtO" style="background:#333;color:#ccc;border:1px solid #555;padding:8px 20px;border-radius:6px;cursor:pointer"&gt;Next occasion →&lt;/button&gt;
        &lt;/div&gt;`;
      } else {
        action = `&lt;div style="background:#252525;border:1px solid #555;border-radius:6px;padding:14px;text-align:center"&gt;
          &lt;p style="margin:0;color:#fff"&gt;Occasion ${occ+1}: &lt;strong&gt;not detected.&lt;/strong&gt;&lt;/p&gt;
          &lt;p style="margin:8px 0 0;color:#999;font-size:13px"&gt;Your survey drew a blank. What do you think happened to this animal?&lt;/p&gt;
        &lt;/div&gt;
        &lt;div style="display:flex;gap:12px;justify-content:center;margin-top:12px"&gt;
          &lt;button id="dBtn" style="background:#3a1a1a;color:#FF5733;border:2px solid #FF5733;padding:10px 28px;border-radius:6px;cursor:pointer;font-weight:bold"&gt;✗ Dead&lt;/button&gt;
          &lt;button id="hBtn" style="background:#2e2a10;color:#FFD700;border:2px solid #FFD700;padding:10px 28px;border-radius:6px;cursor:pointer;font-weight:bold"&gt;? Hiding&lt;/button&gt;
        &lt;/div&gt;`;
      }
    }

    el.innerHTML = `
      &lt;div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"&gt;
        &lt;h3 style="margin:0;color:#fff"&gt;${a.id} — Dead or hiding?&lt;/h3&gt;
        &lt;span style="font-size:12px;color:#666"&gt;${ai+1} / ${animals.length}&lt;/span&gt;
      &lt;/div&gt;
      &lt;p style="color:#999;font-size:13px;margin-bottom:14px"&gt;Tagged and released at occasion 1. Watch each survey unfold. When there is a non-detection, make your call.&lt;/p&gt;
      ${tiles}${action}`;

    el.querySelector("#nxtO")?.addEventListener("click",  () =&gt; { guesses[occ]=null; occ++; draw(); });
    el.querySelector("#dBtn")?.addEventListener("click",  () =&gt; { guesses[occ]="d";  occ++; draw(); });
    el.querySelector("#hBtn")?.addEventListener("click",  () =&gt; { guesses[occ]="h";  occ++; draw(); });
    el.querySelector("#revBtn")?.addEventListener("click",() =&gt; { phase="revealed"; draw(); });
    el.querySelector("#nxtA")?.addEventListener("click",  () =&gt; { ai++; occ=0; guesses=[]; phase="playing"; draw(); });
  }

  draw();
  return el;
}









The problem
To describe these two competing explanations precisely, we need to name two quantities. The first is \(p\), the probability of detecting an individual that is alive and present during a survey. The second is \(\phi\) (the Greek letter “phi”), the probability an individual survives from one survey to the next. These two quantities sit at the heart of everything that follows in this tutorial.
When you do not recapture a tagged animal, you are facing two competing hypotheses:

Hypothesis A: The animal is alive but you missed it. This happens with probability \(\phi \times (1 - p)\): the animal survived (\(\phi\)) the interval between surveys but you failed to detect it (\(1 - p\), the probability of not seeing it).
Hypothesis B: The animal is dead. This happens with probability \(1 - \phi\): the animal did not survive the time between surveys.

Both predict the same observation; 0. When all you have is a capture occasion you cannot tell them apart. Use the sliders below to explore how the balance between these two explanations shifts depending on the true values of \(\phi\) and \(p\).


Code
viewof phi_bar = Inputs.range([0.05, 0.99], {
  value: 0.75,
  step: 0.01,
  label: "Survival probability (\u03c6)"
})









Code
viewof p_bar = Inputs.range([0.05, 0.99], {
  value: 0.40,
  step: 0.01,
  label: "Detection probability (p)"
})









